pub enum LoadError {
    Xml {
        definition: Option<String>,
        line: u64,
        message: String,
    },
    UnknownContext {
        definition: String,
        context: String,
        reference: String,
    },
    UnknownKeywordList {
        definition: String,
        list: String,
    },
    UnknownFormat {
        definition: String,
        format: String,
    },
    DuplicateDefinition {
        name: String,
    },
    License {
        name: String,
        license: String,
    },
}
